#!/usr/bin/env bash
set -euo pipefail
command -v python3 >/dev/null || { echo "Python 3 is required" >&2; exit 1; }
exec python3 - "$0" "$@" <<'TRU_PY_END'
import argparse, base64, contextlib, datetime, fcntl, hashlib, json, os
from pathlib import Path
import shutil, stat, subprocess, sys, tempfile, uuid, zlib

PATCH_ID = 'TRU_PEER_COMMS_01_R2_TRU_CORE'
BUNDLE_SHA = '259c7579467e870310661d599a292a8b34dcbce4eddb0fcf1d1197670478b4d4'

def sha(data): return hashlib.sha256(data).hexdigest()

def file_hash(path):
    if path.is_symlink(): raise RuntimeError('Refusing symlink: '+str(path))
    if not path.exists(): return None
    if not path.is_file(): raise RuntimeError('Not a regular file: '+str(path))
    value=hashlib.sha256()
    with path.open('rb') as stream:
        for block in iter(lambda:stream.read(1048576),b''): value.update(block)
    return value.hexdigest()

def sync_dir(path):
    fd=os.open(str(path),os.O_RDONLY|os.O_DIRECTORY)
    try: os.fsync(fd)
    finally: os.close(fd)

def atomic_write(path,data,meta=None):
    fd,tmp=tempfile.mkstemp(prefix='.'+path.name+'.peer-comms-',dir=str(path.parent))
    try:
        with os.fdopen(fd,'wb') as stream:
            stream.write(data); stream.flush()
            os.fchmod(stream.fileno(),meta['mode'] if meta else 0o644)
            if meta: os.fchown(stream.fileno(),meta['uid'],meta['gid'])
            os.fsync(stream.fileno())
        os.replace(tmp,path); sync_dir(path.parent)
    finally:
        if os.path.exists(tmp): os.unlink(tmp)

def metadata(path):
    st=path.stat()
    return {'mode':stat.S_IMODE(st.st_mode),'uid':st.st_uid,'gid':st.st_gid}

def save_record(backup,record):
    atomic_write(backup/'manifest.json',(json.dumps(record,indent=2)+'\n').encode(),
                 {'mode':0o600,'uid':os.getuid(),'gid':os.getgid()})

def target(root,relative):
    rel=Path(relative)
    if rel.is_absolute() or '..' in rel.parts: raise RuntimeError('Unsafe package path')
    current=root
    for part in rel.parts:
        current=current/part
        if current.is_symlink(): raise RuntimeError('Refusing symlink target/component: '+str(current))
    if not current.parent.is_dir(): raise RuntimeError('Missing target directory: '+str(current.parent))
    return current

def get_roots(args):
    core=Path(args.core).expanduser().resolve(strict=True)
    if not (core/'src/blockchain.cpp').is_file(): raise RuntimeError('--core must contain src/blockchain.cpp')
    roots={'core':str(core)}
    if args.web:
        web=Path(args.web).expanduser().resolve(strict=True)
        if not (web/'script.js').is_file(): raise RuntimeError('--web must contain script.js')
        roots['web']=str(web)
    return roots

def get_binary(args,roots):
    if args.source_only: return None
    if args.binary:
        path=Path(args.binary).expanduser().absolute()
        if file_hash(path) is None: raise RuntimeError('Executable not found: '+str(path))
        return path
    root=Path(roots['core'])
    choices=[p for p in (root/'tru_advanced',root/'build/tru_advanced',root/'build/bin/tru_advanced') if p.is_file() and not p.is_symlink()]
    if len(choices)>1: raise RuntimeError('Multiple executables found; specify --binary with the exact tru_advanced path')
    return choices[0] if choices else None

def stopped(roots,binary=None):
    if not sys.platform.startswith('linux'): raise RuntimeError('Apply/revert require Linux process checks; extract can be used for offline inspection')
    core=Path(roots['core'])
    for item in Path('/proc').iterdir():
        if not item.name.isdigit(): continue
        try:
            if (item/'comm').read_text().strip()!='tru_advanced': continue
            exe=Path(os.readlink(item/'exe').replace(' (deleted)',''))
            cwd=Path(os.readlink(item/'cwd'))
        except FileNotFoundError: continue
        except PermissionError:
            raise RuntimeError('Cannot inspect running tru_advanced; stop it and rerun with sufficient permissions')
        if exe==binary or core==cwd or core in cwd.parents or core in exe.parents:
            raise RuntimeError('Stop tru_advanced gracefully first (PID '+item.name+'); this patch never kills processes')

@contextlib.contextmanager
def tree_lock(core):
    fd=os.open(str(core),os.O_RDONLY|os.O_DIRECTORY)
    try:
        fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
        yield
    finally: os.close(fd)

def selected(bundle,roots): return [f for f in bundle['files'] if f['root'] in roots]

def check(bundle,roots,required=None):
    results=[]
    for entry in selected(bundle,roots):
        path=target(Path(roots[entry['root']]),entry['path'])
        current=file_hash(path)
        state='original' if current==entry['before'] else 'patched' if current==entry['after'] else 'MISMATCH'
        results.append((entry,path,state))
    bad=[str(p) for _,p,s in results if s=='MISMATCH' or (required and s!=required)]
    if bad: raise RuntimeError('File hash preflight failed; no writes made.\n'+'\n'.join(bad))
    if len({s for _,_,s in results})>1: raise RuntimeError('Mixed original/patched files; use the prior backup to revert first')
    return results

def copy_backup(source,destination):
    shutil.copy2(source,destination)
    with destination.open('rb') as stream: os.fsync(stream.fileno())
    sync_dir(destination.parent)

def load_record(path,bundle):
    backup=Path(path).expanduser().resolve(strict=True)
    record=json.loads((backup/'manifest.json').read_text())
    if record.get('patch')!=PATCH_ID or record.get('bundle_sha256')!=BUNDLE_SHA: raise RuntimeError('Wrong patch/backup identity')
    expected={(f['root'],f['path']):(f['before'],f['after']) for f in selected(bundle,record['roots'])}
    actual={(f['root'],f['path']):(f['before'],f['after']) for f in record['files']}
    if actual!=expected or len(actual)!=len(record['files']): raise RuntimeError('Backup manifest does not match package pins')
    return backup,record

def restore(backup,record,source_only=False):
    # Complete preflight before restoring any file. Interrupted installs/reverts
    # may contain either original or patched bytes, never unrecognized edits.
    for entry in record['files']:
        path=target(Path(record['roots'][entry['root']]),entry['path'])
        if file_hash(path) not in (entry['before'],entry['after']): raise RuntimeError('Revert would overwrite later changes: '+str(path))
        if entry['before'] is not None and file_hash(backup/'originals'/entry['backup'])!=entry['before']: raise RuntimeError('Backup checksum failed: '+entry['path'])
    binary=record.get('binary')
    if binary and not source_only:
        if file_hash(backup/'originals'/'core-binary')!=binary['before']: raise RuntimeError('Executable backup checksum failed')
        actual=file_hash(Path(binary['path']))
        if not actual or actual not in (binary['before'],binary.get('sealed_sha256')):
            raise RuntimeError('Executable changed but is not sealed. After your intended build run seal, or use revert --source-only and rebuild the restored source.')
    recover=backup/'pre-revert'; recover.mkdir(exist_ok=True,mode=0o700)
    record['status']='reverting'; save_record(backup,record)
    for entry in reversed(record['files']):
        path=target(Path(record['roots'][entry['root']]),entry['path']); actual=file_hash(path)
        if actual==entry['before']: continue
        if actual!=entry['after']: raise RuntimeError('Concurrent edit during revert: '+str(path))
        copy_backup(path,recover/(entry['backup']+'-'+uuid.uuid4().hex[:8]))
        if entry['before'] is None:
            path.unlink(); sync_dir(path.parent) # exact new header, with recovery copy above
        else: atomic_write(path,(backup/'originals'/entry['backup']).read_bytes(),entry['metadata'])
    if binary and not source_only:
        path=Path(binary['path']); actual=file_hash(path)
        if actual!=binary['before']:
            if actual!=binary.get('sealed_sha256'): raise RuntimeError('Executable changed during revert')
            copy_backup(path,recover/('core-binary-'+uuid.uuid4().hex[:8]))
            atomic_write(path,(backup/'originals'/'core-binary').read_bytes(),binary['metadata'])
    record['status']='reverted-source-only' if source_only else 'reverted'; save_record(backup,record)

def apply(bundle,args):
    roots=get_roots(args); binary=get_binary(args,roots)
    if not binary and not args.source_only: raise RuntimeError('Executable not found. Supply --binary PATH for binary rollback, or --source-only for an offline source tree.')
    with tree_lock(roots['core']):
        stopped(roots,binary); results=check(bundle,roots)
        if all(s=='patched' for _,_,s in results): print('ALREADY_PATCHED; no writes'); return
        base=Path(roots['core'])/'.tru-patch-backups'
        if base.is_symlink(): raise RuntimeError('Refusing symlink backup directory')
        base.mkdir(exist_ok=True,mode=0o700)
        stamp=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ')
        backup=base/(PATCH_ID+'-'+stamp+'-'+uuid.uuid4().hex[:8])
        backup.mkdir(mode=0o700); (backup/'originals').mkdir(mode=0o700)
        record={'patch':PATCH_ID,'bundle_sha256':BUNDLE_SHA,'roots':roots,'status':'preparing','files':[],'binary':None}
        for index,(entry,path,_) in enumerate(results):
            item={k:entry[k] for k in ('root','path','before','after')}
            item.update(backup=f'{index:03d}',metadata=metadata(path) if path.exists() else None)
            if entry['before'] is not None:
                copy_backup(path,backup/'originals'/item['backup'])
                if file_hash(backup/'originals'/item['backup'])!=entry['before']: raise RuntimeError('Source changed while backing up: '+str(path))
            record['files'].append(item)
        if binary:
            info={'path':str(binary),'before':file_hash(binary),'metadata':metadata(binary)}
            copy_backup(binary,backup/'originals'/'core-binary')
            if file_hash(backup/'originals'/'core-binary')!=info['before']: raise RuntimeError('Executable changed during backup')
            record['binary']=info
        record['status']='prepared'; save_record(backup,record)
        print('BACKUP='+str(backup),flush=True)
        try:
            record['status']='applying'; save_record(backup,record)
            for (entry,path,_),item in zip(results,record['files']):
                if file_hash(path)!=entry['before']: raise RuntimeError('Concurrent edit: '+str(path))
                atomic_write(path,base64.b64decode(entry['content']),item['metadata'])
                if file_hash(path)!=entry['after']: raise RuntimeError('Post-write checksum failed: '+str(path))
            record['status']='applied'; save_record(backup,record)
        except BaseException:
            try: restore(backup,record)
            except BaseException as error: print('RECOVERY_REQUIRED: '+str(error)+'; backup='+str(backup),file=sys.stderr)
            raise
        print('APPLY=PASS. Core binary has NOT been rebuilt or replaced. Rebuild tru_advanced, then seal this backup before restarting.')
        if args.source_only: print('SOURCE_ONLY: no executable backup; rollback requires rebuilding restored source.')

def extract(bundle,destination):
    root=Path(destination).expanduser().absolute()
    if root.exists(): raise RuntimeError('Extract destination must not already exist')
    root.mkdir(parents=True,mode=0o700)
    for entry in bundle['files']:
        path=root/entry['root']/entry['path']; path.parent.mkdir(parents=True,exist_ok=True)
        path.write_bytes(base64.b64decode(entry['content']))
    for relative,encoded in bundle['extras'].items():
        path=root/relative; path.parent.mkdir(parents=True,exist_ok=True)
        path.write_bytes(base64.b64decode(encoded))
    print('EXTRACTED='+str(root))

def main(bundle):
    ap=argparse.ArgumentParser(description='TRU PEER-COMMS-01 R2 TRU-Core clean-tree variant: pinned Core/explorer patch and guarded revert')
    sub=ap.add_subparsers(dest='command',required=True)
    for name in ('check','apply'):
        parser=sub.add_parser(name); parser.add_argument('--core',required=True)
        parser.add_argument('--web'); parser.add_argument('--binary')
        parser.add_argument('--source-only',action='store_true')
    for name in ('verify','seal','revert'):
        parser=sub.add_parser(name); parser.add_argument('--backup',required=True)
        if name=='revert': parser.add_argument('--source-only',action='store_true')
    sub.add_parser('readme'); sub.add_parser('self-test')
    parser=sub.add_parser('extract'); parser.add_argument('--output',required=True)
    args=ap.parse_args()
    if args.command=='readme': print(base64.b64decode(bundle['extras']['README.md']).decode()); return
    if args.command=='extract': extract(bundle,args.output); return
    if args.command=='self-test':
        with tempfile.TemporaryDirectory(prefix='tru-peer-package-') as work:
            destination=Path(work)/'bundle'; extract(bundle,destination)
            tree=destination/'core'; shutil.copytree(destination/'web',tree/'web')
            for file in (destination/'reference').iterdir(): shutil.copyfile(file,tree/'src'/file.name)
            subprocess.run([sys.executable,str(destination/'tests/run_checks.py'),'--tree',str(tree)],check=True)
        return
    if args.command=='check':
        roots=get_roots(args); results=check(bundle,roots)
        print('SOURCE_PINS='+('ALREADY_PATCHED' if all(s=='patched' for _,_,s in results) else 'BASELINE_READY'))
        print('FILES='+str(len(results))); print('CORE='+roots['core']); print('WEB='+roots.get('web','Core-only mode'))
        print('BINARY='+str(get_binary(args,roots) or 'not found; specify --binary or --source-only for apply')); return
    if args.command=='apply': apply(bundle,args); return
    backup,record=load_record(args.backup,bundle)
    with tree_lock(record['roots']['core']):
        if args.command=='verify':
            check(bundle,record['roots'],required='patched'); print('INSTALLED_SOURCE_PINS=PASS'); return
        if args.command=='seal':
            if record['status']!='applied' or not record['binary']: raise RuntimeError('Seal requires an applied patch with an executable backup')
            check(bundle,record['roots'],required='patched')
            current=file_hash(Path(record['binary']['path']))
            if not current or current==record['binary']['before']: raise RuntimeError('Executable missing/unchanged; successfully rebuild the intended tru_advanced first')
            record['binary']['sealed_sha256']=current; save_record(backup,record)
            print('BUILD_HASH_SEALED='+current+' (records your selected build; not runtime validation)'); return
        stopped(record['roots'],Path(record['binary']['path']) if record.get('binary') else None)
        restore(backup,record,args.source_only)
        print('REVERT=PASS; original source/web restored; recovery copies retained in '+str(backup/'pre-revert'))
        print('ORIGINAL_EXECUTABLE_RESTORED=YES' if record.get('binary') and not args.source_only else 'Rebuild restored source before restarting Core.')

if __name__=='__main__':
    try:
        installer=Path(sys.argv.pop(1))
        encoded=installer.read_bytes().split(b'\n__TRU_PEER_COMMS_PAYLOAD__\n',1)[1].split(b'\nTRU_BLOB_END',1)[0]
        raw=zlib.decompress(base64.b64decode(encoded))
        if sha(raw)!=BUNDLE_SHA: raise RuntimeError('Embedded package checksum failed')
        package=json.loads(raw)
        for entry in package['files']:
            if sha(base64.b64decode(entry['content']))!=entry['after']: raise RuntimeError('Embedded source checksum failed')
        main(package)
    except (Exception,KeyboardInterrupt) as error:
        print('ERROR: '+str(error),file=sys.stderr); sys.exit(1)

